#include <stdio.h>
#include <math.h>

typedef struct { float x, y, z; } V;

static V vc(float x, float y, float z) { V r; r.x = x; r.y = y; r.z = z; return r; }
static V vadd(V a, V b) { return vc(a.x + b.x, a.y + b.y, a.z + b.z); }
static V vsub(V a, V b) { return vc(a.x - b.x, a.y - b.y, a.z - b.z); }
static V vmul(V a, float s) { return vc(a.x * s, a.y * s, a.z * s); }
static float vdot(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static float vlen(V a) { return (float)sqrt((double)vdot(a, a)); }
static V vnorm(V a) { float l = vlen(a); return vc(a.x / l, a.y / l, a.z / l); }

typedef struct { V o, d; } Ray;
typedef struct { float t; V p, n; int hit; } Hit;
typedef struct { V c; float r; } Sph;

static Ray rmake(V o, V d) { Ray r; r.o = o; r.d = vnorm(d); return r; }
static V rat(Ray r, float t) { return vadd(r.o, vmul(r.d, t)); }

static Hit sphere_hit(Ray ray, Sph s)
{
    Hit h; h.t = 0; h.p = vc(0, 0, 0); h.n = vc(0, 0, 0); h.hit = 0;
    V oc = vsub(ray.o, s.c);
    float a = vdot(ray.d, ray.d);
    float b = 2.0f * vdot(oc, ray.d);
    float c = vdot(oc, oc) - s.r * s.r;
    float disc = b * b - 4.0f * a * c;
    if (disc < 0.0f) return h;
    float t = (float)((-(double)b - sqrt((double)disc)) / (2.0 * (double)a));
    if (t < 0.001f) {
        t = (float)((-(double)b + sqrt((double)disc)) / (2.0 * (double)a));
        if (t < 0.001f) return h;
    }
    h.hit = 1;
    h.t = t;
    h.p = rat(ray, t);
    h.n = vnorm(vsub(h.p, s.c));
    return h;
}

static Hit plane_hit(Ray ray, float py)
{
    Hit h; h.t = 0; h.p = vc(0, 0, 0); h.n = vc(0, 0, 0); h.hit = 0;
    if (fabsf(ray.d.y) < 1e-4f) return h;
    float t = (py - ray.o.y) / ray.d.y;
    if (t < 0.001f) return h;
    h.hit = 1;
    h.t = t;
    h.p = rat(ray, t);
    h.n = vc(0, 1, 0);
    return h;
}

static V sky(Ray r)
{
    float t = 0.5f * (r.d.y + 1.0f);
    V w = vc(1, 1, 1), b = vc(0.5f, 0.7f, 1.0f);
    return vadd(vmul(w, 1.0f - t), vmul(b, t));
}

static int shadowed(V p, V ld, Sph s)
{
    Ray sr = rmake(p, ld);
    return sphere_hit(sr, s).hit;
}

static V trace(Sph s, V light, Ray ray)
{
    Hit sh = sphere_hit(ray, s);
    Hit ph = plane_hit(ray, -1.5f);
    Hit h; int is_sphere = 0;
    if (sh.hit && (!ph.hit || sh.t < ph.t)) { h = sh; is_sphere = 1; }
    else if (ph.hit) { h = ph; is_sphere = 0; }
    else return sky(ray);

    float diff = (float)fmax((double)vdot(h.n, light), 0.0);
    V sp = vadd(h.p, vmul(h.n, 0.001f));
    if (shadowed(sp, light, s)) diff = 0.0f;
    float amb = 0.2f;
    diff = amb + (1.0f - amb) * diff;

    V col;
    if (is_sphere) col = vc(1.0f, 0.2f, 0.2f);
    else {
        int chk = (((int)(floor((double)h.p.x) + floor((double)h.p.z))) & 1) == 0;
        col = chk ? vc(0.9f, 0.9f, 0.9f) : vc(0.4f, 0.4f, 0.4f);
    }
    return vmul(col, diff);
}

int main(void)
{
    const int W = 2400, H = 1800;
    V origin = vc(0, 0, 0);
    float vh = 2.0f;
    float vw = ((float)W / (float)H) * vh;
    float focal = 1.0f;
    V horiz = vc(vw, 0, 0);
    V vert = vc(0, vh, 0);
    V depth = vc(0, 0, focal);
    V llc = vsub(vsub(vsub(origin, vmul(horiz, 0.5f)), vmul(vert, 0.5f)), depth);

    Sph s; s.c = vc(0.0f, -0.5f, -5.0f); s.r = 1.0f;
    V light = vnorm(vc(1.0f, 1.0f, -1.0f));

    FILE *f = fopen("reconstructed.ppm", "w");
    if (!f) return 1;
    fprintf(f, "P3\n%d %d\n255\n", W, H);

    for (int j = 0; j < H; j++) {
        float v = (float)j / (float)(H - 1);
        for (int i = 0; i < W; i++) {
            float u = (float)i / (float)(W - 1);
            V dir = vadd(llc, vadd(vmul(horiz, u), vsub(vmul(vert, 1.0f - v), origin)));
            Ray ray = rmake(origin, dir);
            V c = trace(s, light, ray);
            float cr = (float)fmin(fmax((double)c.x, 0.0), 1.0);
            float cg = (float)fmin(fmax((double)c.y, 0.0), 1.0);
            float cb = (float)fmin(fmax((double)c.z, 0.0), 1.0);
            fprintf(f, "%d %d %d\n", (int)(255.99f * cr), (int)(255.99f * cg), (int)(255.99f * cb));
        }
    }
    fclose(f);
    return 0;
}

